import { isEmpty } from 'lodash-es';
import React, {
  PropsWithChildren,
  forwardRef,
  useImperativeHandle,
  useMemo,
  useRef,
} from 'react';

import { StoreProvider } from './components/StoreProvider.js';
import { TreeMapChartLayout } from './components/TreeMapChartLayout.js';
import { DEFAULT_HEIGHT, MIN_NODE_SIZE_LIMIT } from './constants.js';
import { ChartLegendContext } from './context/ChartLegendContext.js';
import { FormatterContext } from './context/FormatterContext.js';
import { ToolbarContext } from './context/ToolbarContext.js';
import { TreeMapDataContext } from './context/TreeMapDataContext.js';
import { buildAndDownloadCsv } from './functions/build-and-download-csv.js';
import { mapToInternalTreemapData } from './functions/map-to-internal-treemap-data.js';
import { useTreeMapChartConfig } from './hooks/useTreeMapChartConfig.js';
import { Tooltip } from './slots/Tooltip.js';
import { Legend as TreeMapChartLegend } from './slots/TreeMapChartLegend.js';
import type { TreeMapContextConfig } from './types/treemap-chart.config.js';
import { TreeMapProps, TreeMapRef } from './types/treemap.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { getChartStatesTemplates } from '../core/components/chart-states/functions/get-chart-states-template.js';
import { ChartSeriesActionContext } from '../core/components/series-action/ChartSeriesActionContext.js';
import { EmptyStateSlot } from '../core/slots/chart-states/EmptyStateSlot.js';
import { ErrorStateSlot } from '../core/slots/chart-states/ErrorStateSlot.js';
import { ChartType } from '../core/types/chart-types.js';

const _TreeMap = forwardRef<HTMLDivElement, PropsWithChildren<TreeMapProps>>(
  (props, forwardedRef): JSX.Element => {
    const {
      data,
      children,
      seriesActions,
      height = DEFAULT_HEIGHT,
      className,
      style,
    } = props;

    const {
      colorPalette,
      formatter,
      loading,
      minNodeSize,
      truncationMode,
      legend,
      toolbar,
    } = useTreeMapChartConfig(props);

    const emptyData =
      isEmpty(data) ||
      data.tree.nodes === undefined ||
      data.tree.nodes.length === 0;

    const { tree, unit } = data;

    const internalData = useMemo(() => {
      return mapToInternalTreemapData(tree, unit, colorPalette);
    }, [tree, unit, colorPalette]);

    const { emptyState, errorState } = getChartStatesTemplates(children);

    const treeMapRef = useRef<TreeMapRef>(null);

    const rootRef = useMergeRefs<TreeMapRef | HTMLDivElement>([
      forwardedRef,
      treeMapRef,
    ]);

    const minNodeSizeLimit =
      minNodeSize < MIN_NODE_SIZE_LIMIT ? MIN_NODE_SIZE_LIMIT : minNodeSize;

    useImperativeHandle(forwardedRef, () => {
      if (treeMapRef.current) {
        treeMapRef.current.getConfig = () => {
          const config: TreeMapContextConfig = {
            colorPalette,
            formatter,
            loading,
            minNodeSize,
            truncationMode,
            legend,
          };

          return JSON.stringify({ type: ChartType.Treemap, ...config });
        };
        treeMapRef.current.downloadData = () => {
          return buildAndDownloadCsv(internalData.tree);
        };
      }

      // We are ignoring this eslint rule as this will always be defined since we are relying on the consumer to pass the reference value.
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      return treeMapRef.current!;
    });

    return (
      <TreeMapDataContext.Provider value={internalData}>
        <ChartSeriesActionContext.Provider
          value={{
            chartSeriesActions: seriesActions,
          }}
        >
          <FormatterContext.Provider
            value={{
              formatter,
              truncationMode,
            }}
          >
            <ChartLegendContext.Provider value={legend}>
              <ToolbarContext.Provider value={toolbar}>
                <StoreProvider>
                  <TreeMapChartLayout
                    ref={rootRef}
                    minNodeSize={minNodeSizeLimit}
                    height={height}
                    emptyState={emptyState}
                    errorState={errorState}
                    isEmpty={emptyData}
                    loading={loading}
                    className={className}
                    style={style}
                  />
                </StoreProvider>
              </ToolbarContext.Provider>
            </ChartLegendContext.Provider>
          </FormatterContext.Provider>
        </ChartSeriesActionContext.Provider>
      </TreeMapDataContext.Provider>
    );
  },
);

/**
 * The `TreeMap` visualizes the distribution of hierarchical data.
 * It uses nested rectangles of different sizes and colors to show
 * how much each category or subcategory contributes to the whole
 * data set.
 */
export const TreeMap = Object.assign(_TreeMap, {
  Legend: TreeMapChartLegend,
  Tooltip,
  EmptyState: EmptyStateSlot,
  ErrorState: ErrorStateSlot,
});
